local _, WFI = ...
WFI.Data.add("quest", {
  [8149] = { "Onorare un eroe", "Recati all'Uther's Tomb, nelle Western Plaguelands, e usa l'Uther's Tribute presso la sua statua, poi torna da Wagner Hammerstrike, fuori Ironforge, prima che finisca l'Harvest Festival.", "Durante l'Harvest Festival di Azeroth rendiamo grazie agli eroi per i sacrifici, in alcuni casi il sacrificio supremo, che hanno compiuto per noi. L'Alliance riconosce molti eroi, ma nessuno ha una storia più tragica di quella di Uther Lightbringer.\n\nAiutaci a onorare Uther portando questa offerta alla sua tomba, nelle Western Plaguelands. Ponila presso la sua statua, poi torna da me. Resterò qui solo fino alla fine della festa, quindi non perdere tempo a rendere omaggio a Uther.", "Hai fatto il viaggio fino all'Uther's Tomb e vi hai deposto l'offerta?\n\nPuò essere un viaggio pericoloso per gli avventurieri meno esperti; un modo più sicuro, relativamente parlando, per arrivarci potrebbe essere risalire verso nord, nelle Plaguelands, dal fiume che attraversa Hillsbrad. Nasce da un lago adiacente a Sorrow Hill; procedi verso ovest su per le colline, tenendoti alla larga dalla tomba vicina... una tomba infestata dalla Scourge.", "Era un eroe tra gli eroi, Uther. Non riesco nemmeno a immaginare l'angoscia che provò quando Arthas, il suo allievo migliore e qualcuno che Uther amava come un figlio, tradì l'intera umanità. Eppure si levò per cercare di fermare Arthas, e per questo sarà ricordato per sempre come un vero paladino. La sua lotta durò fino alla fine, pensando solo a coloro che poteva salvare.\n\nGrazie, {name}. Oggi hai reso omaggio a un grande eroe, onorando il suo spirito e lo spirito dell'Harvest Festival.", 0x9e2b2607, 0x95fd1a45, 0xdb133806, 0x7489d4e8, 0x391a64b5, "....." },
  [8150] = { "Onorare un eroe", nil, nil, nil, nil, 0x9e2b2607, nil, nil, nil, nil, ".mmmm" },
  [8266] = { "Nastri del sacrificio", nil, nil, "Capisco che a volte possa essere difficile avere la meglio a Warsong Gulch. Eppure il tuo impegno per noi, anche quando non arriva la vittoria, è importante.\n\nSe completi una delle prove a Warsong Gulch senza ottenere la vittoria, riceverai comunque un Ribbons of Sacrifice. Portamelo, così le Sentinels potranno ricompensarti per aver agito in nostro favore... anche se questa volta non sei <riuscito/riuscita> a vincere.", "Beh, non sei <fuggito/fuggita> davanti alla sconfitta. Hai tenuto la tua posizione, {name}, ed è questo, in fondo, che fa <un/una> <vero/vera> <eroe/eroina>. Senza dubbio vincerai la prossima volta... ma intanto ti ringraziamo per il tuo impegno.", 0x8ea61f00, nil, nil, 0xe9324b2e, 0xc338822b, ".mm.." },
  [8268] = { "Nastri del sacrificio", nil, nil, nil, "Beh, non sei <fuggito/fuggita> davanti alla sconfitta. Hai tenuto la tua posizione, {name}, ed è questo, in fondo, che fa <un/una> <vero/vera> <eroe/eroina>. Senza dubbio vincerai la prossima volta... ma intanto ti ringraziamo per il tuo impegno.", 0x8ea61f00, nil, nil, nil, 0xc338822b, ".mmm." },
  [8290] = { nil, "Entra a Warsong Gulch e sconfiggi l'Horde, ottieni un Warsong Gulch Mark of Honor e torna dalla Sentinel Farsong, al Silverwing Grove.", "Oltre questa galleria troverai un campo di conflitto e tumulto, giovane {class}. L'Horde continua a devastare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.\n\nEntra a Warsong Gulch e difendi Silverwing Hold. Respingi le forze d'invasione dell'Horde!\n\nFallo e guadagnerai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", nil, nil, nil, 0xfeb46d9a, 0xd5134582, nil, nil, "m..mm" },
  [8291] = { "Sconfiggi gli invasori!", "Entra a Warsong Gulch e sconfiggi l'Horde, ottieni un Silverwing Talisman of Merit e torna dalla Sentinel Farsong, al Silverwing Grove.", "Oltre questa galleria troverai un campo di conflitto e tumulto, giovane {class}. L'Horde continua a devastare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.\n\nEntra a Warsong Gulch e difendi Silverwing Hold. Respingi le forze d'invasione dell'Horde!\n\nFallo e guadagnerai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", "Hai combattuto a Warsong Gulch e difeso Silverwing Hold?", "Hai dimostrato il tuo valore nei nostri sforzi a Warsong Gulch. Continua ad aiutare la causa e portami altri Marks of Honor. Fallo, e guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xbdddd230, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [8308] = { nil, nil, nil, "Oh, povera me.", nil, nil, nil, nil, 0x9e26ead5, nil, "mmm.m" },
  [8357] = { "Balli in cambio di marzapane", "Fai l'emote del ballo davanti a Innkeeper Saelienne e riceverai in cambio del Darnassus Marzipan!", "Anche se fai dolcetto o scherzetto per un bambino malato, devi comunque fare uno scherzetto per avere il dolcetto! Non possiamo mica cambiare la tradizione, no?\n\nCredo che oggigiorno il prezzo di un pezzo di marzapane sia scatenarsi e ballare! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò del gustoso marzapane!", "Sai ballare, vero? Prova così: metti dentro il piede destro... poi il piede destro fuori... il piede destro dentro... e scuoti tutto quanto...", "Sei proprio una macchina da ballo, {name}!\n\nEcco il tuo dolcetto per essere <stato/stata> al gioco. Buon Hallow's End, e salutami tanto il tuo piccolo amico malato! Spero che guarisca presto.", 0xe471aaf9, 0x8d5f785c, 0x8c369374, 0xf9d6b077, 0x85f6bca9, "....." },
  [8360] = { "Balli in cambio di marzapane", nil, "Anche se fai dolcetto o scherzetto per un bambino malato, devi comunque fare uno scherzetto per avere il dolcetto! Non possiamo mica cambiare la tradizione, no?\n\nCredo che oggigiorno il prezzo di un pezzo di marzapane sia scatenarsi e ballare! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò del gustoso marzapane!", "Sai ballare, vero? Prova così: metti dentro il piede destro... poi il piede destro fuori... il piede destro dentro... e scuoti tutto quanto...", "Sei proprio una macchina da ballo, {name}!\n\nEcco il tuo dolcetto per essere <stato/stata> al gioco. Buon Hallow's End, e salutami tanto il tuo piccolo amico malato! Spero che guarisca presto.", 0xe471aaf9, nil, 0x8c369374, 0xf9d6b077, 0x85f6bca9, ".m..." },
  [8499] = { nil, nil, nil, "Oh, una spedizione da mio fratello? Splendido! Oggi la fortuna mi sorride davvero!", nil, nil, nil, nil, 0x89b01d8f, nil, "mmm.m" },
  [8619] = { nil, nil, nil, nil, "È bello sapere che la gente di queste terre rende ancora omaggio alle razze antiche. Ti auguro ogni bene, {name}, e ti offro questo pegno...", nil, nil, nil, nil, 0xdc5611ad, "mmmm." },
