  [8727] = { nil, nil, nil, nil, "I cieli, con le loro stelle innumerevoli, custodiscono le risposte ai misteri della terra, {name}. Potranno allora i saggi, e i fortunati, alzare lo sguardo e trovare la verità?", nil, nil, nil, nil, 0x3da1f0cc, "mmmm." },
  [8733] = { "Eranikus, il tiranno del sogno", "Vai sul continente di Teldrassil e trova l'agente di Malfurion da qualche parte fuori dalle mura di Darnassus.", "Questo è un viaggio di redenzione, eroe. Se oggi fossi ucciso, sarei morto per una causa giusta e retta. Devi recuperare il frammento verde dello scettro. Devi purificare Eranikus dalla corruzione che gli Old Gods gli hanno inflitto.\n\nVai a Darnassus. Appena fuori dalle mura della città troverai uno dei miei agenti. Questo agente metterà in moto le cose per noi e informerà Tyrande dei nostri piani senza allertare Staghelm.\n\n<Malfurion sospira.>\n\nUna caduta in disgrazia preparata in mille anni...", nil, "Il fuoco fatuo è silenzioso, a parte un ronzio sommesso. Stranamente, riesce a comunicare con te attraverso il pensiero.", 0xbe6d8014, 0x357b9a72, 0xd703f3de, nil, 0x9acaa65e, "...m." },
  [8734] = { "Tyrande e Remulos", "Vai a Moonglade e parla con Keeper Remulos.", "Tyrande sarà avvisata, mortale. Shan'do Stormrage mi ha preparato a questa eventualità.\n\nOra devi andare a Moonglade e parlare con Remulos. Ti darà altre istruzioni per l'evocazione di Eranikus.\n\nTutti ti auguriamo buona fortuna.", nil, "Sarebbe impossibile strappare Eranikus al sogno, se si rifiutasse. Le sue intenzioni, però, lo costringono a entrare nel nostro mondo. Vuole distruggere la manifestazione vivente di Malfurion. Riuscirci vorrebbe dire la fine di uno dei più potenti alleati del sogno. Se Malfurion cadesse, il Nightmare consumerebbe tutto ciò che resta...", 0x2bb57255, 0x90072af4, 0xad596e43, nil, 0xadfdbec9, "...m." },
  [8811] = { "Un Commendation Signet", nil, nil, "Agli avventurieri che hanno un solo commendation signet, lo cambierò con un piccolo riconoscimento presso Darnassus.\n\nTieni presente che è meglio consegnare una pila di dieci sigilli in una volta; così i tuoi sforzi riceveranno un riconoscimento maggiore. Offriamo il cambio di un singolo sigillo come servizio per chi non ne ha abbastanza per una pila completa di dieci.\n\nDetto questo, sono a tua disposizione se vuoi comunque consegnare un solo sigillo.", "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, 0xd169c818, 0x3fd3f6f6, ".mm.." },
  [8812] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8813] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8814] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8815] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
