  [8817] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8818] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8819] = { "Dieci Commendation Signets", nil, nil, "Accetto i commendation signets dagli avventurieri che li hanno ricevuti nell'adempimento del dovere. Per ogni serie di dieci che mi consegni, farò in modo che tu riceva un riconoscimento significativo delle tue azioni presso Darnassus. Accetto anche gettoni singoli, ma con un riconoscimento molto ridotto. Ci interessano molto di più le grandi imprese, anche se nessuna impresa sarà ignorata.\n\nDetto questo, prenderò volentieri i tuoi sigilli se sei <pronto/pronta> a consegnarne una serie.", "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi sigilli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, {name}, a fare davvero la differenza.\n\nFammi sapere se hai altri sigilli da consegnare; ti aiuterò volentieri con tutti quelli che vuoi cambiare.", 0xc9ab59cb, nil, nil, 0xd21ad71b, 0xd1519e98, ".mm.." },
  [8820] = { "Dieci Commendation Signets", nil, nil, nil, "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi sigilli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, {name}, a fare davvero la differenza.\n\nFammi sapere se hai altri sigilli da consegnare; ti aiuterò volentieri con tutti quelli che vuoi cambiare.", 0xc9ab59cb, nil, nil, nil, 0xd1519e98, ".mmm." },
