  [8860] = { "Festeggiamenti per l'anno nuovo!", "Porta gli Smokywood Supplies all'Innkeeper Allison, a Stormwind.", "Stormwind festeggia l'anno nuovo! Per tutto il giorno oggi si beve gratis, e stanotte ci sarà uno spettacolo di fuochi d'artificio! Dovrebbe essere piuttosto bello... ma anche Booty Bay fa festa oggi; scommetto che sarà ancora meglio!\n\nComunque, l'Innkeeper Allison di Stormwind ha bisogno di una scorta di cibo di Smoky Wood Pasture per sfamare tutti i festaioli. Puoi farmi il favore di consegnargliela?\n\nGrazie, {name}! L'Innkeeper Allison è al Gilded Rose, nel Trade District di Stormwind.", "Salute! Sei qui per la festa? O forse devi solo riposare quei tuoi piedi stanchi...", "Oh, le mie provviste Smokywood! Splendido! Mi serviranno per sfamare tutta la gente in città per i festeggiamenti!\n\nGrazie, {name}. Accetta questo come pagamento, e non dimenticare di bere e ballare con i festaioli là fuori!", 0x3c0ed155, 0x6d031637, 0xa4217aac, 0xf49dbb5c, 0x5c98c2e1, "....." },
  [8861] = { "Festeggiamenti per l'anno nuovo!", nil, nil, nil, nil, 0x3c0ed155, nil, nil, nil, nil, ".mmmm" },
  [8866] = { nil, nil, nil, nil, "È bello sapere che la gente di queste terre rende ancora omaggio alle razze antiche. Ti auguro ogni bene, {name}, e ti offro questo pegno...", nil, nil, nil, nil, 0xdc5611ad, "mmmm." },
  [8867] = { nil, "Lancia 8 Lunar Fireworks e 2 Cluster Fireworks e torna da un Lunar Festival Harbinger in una qualsiasi capitale.", "Ogni anno i druidi di Moonglade celebrano il grande trionfo della nostra città su un male antico.\n\nFesteggiamo la saggezza dei nostri anziani, condividiamo banchetti magnifici e naturalmente... spariamo fuochi d'artificio!\n\nCon una piccola offerta puoi comprare razzi colorati dal nostro venditore. Prova a usare qualcuno dei lanciatori qui intorno, {name}.", "Hai trovato i lanciatori, {name}?", "Ben fatto, {name}.\n\nOra che sei nello spirito giusto, perché non prendi questo invito alla festa di Moonglade?\n\nÈ una celebrazione davvero piacevole, se hai tempo. Condividiamo cibo, bevande, storie e naturalmente... altri fuochi d'artificio!\n\nApri l'invito stando dentro il cerchio della grande luce lunare e sarai <trasportato/trasportata> a Moonglade.", nil, 0xe11116a6, 0x54448a9c, 0xa9be4649, 0xca71c0a7, "m...." },
  [8870] = { "Il Lunar Festival", "Parla con il Lunar Festival Harbinger nel Mystic Ward di Ironforge. Puoi parlare anche con i Lunar Festival Harbingers nelle altre capitali.", "È di nuovo quel periodo dell'anno, {name}! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare alla nostra celebrazione del Lunar Festival. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Ti racconterà di più sulla festa.", nil, "<Benvenuto/Benvenuta>, {name}. Sei qui per unirti ai festeggiamenti?", 0x63b563a9, 0xe3d9f021, 0xb5d3d793, nil, 0xb39733ba, "...m." },
  [8871] = { "Il Lunar Festival", "Parla con il Lunar Festival Harbinger nel Park District di Stormwind. Puoi parlare anche con i Lunar Festival Harbingers nelle altre capitali.", "È di nuovo quel periodo dell'anno, {name}! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare alla nostra celebrazione del Lunar Festival. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Ti racconterà di più sulla festa.", nil, "<Benvenuto/Benvenuta>, {name}. Sei qui per unirti ai festeggiamenti?", 0x63b563a9, 0x31eda9ed, 0xb5d3d793, nil, 0xb39733ba, "...m." },
  [8872] = { "Il Lunar Festival", "Parla con il Lunar Festival Harbinger nel Cenarion Enclave di Darnassus. Puoi parlare anche con i Lunar Festival Harbingers nelle altre capitali.", "È di nuovo quel periodo dell'anno, {name}! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare alla nostra celebrazione del Lunar Festival. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Ti racconterà di più sulla festa.", nil, "<Benvenuto/Benvenuta>, {name}. Sei qui per unirti ai festeggiamenti?", 0x63b563a9, 0x8e1fa3bb, 0xb5d3d793, nil, 0xb39733ba, "...m." },
  [8873] = { "Il Lunar Festival", nil, "È di nuovo quel periodo dell'anno, {name}! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare alla nostra celebrazione del Lunar Festival. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Ti racconterà di più sulla festa.", nil, "<Benvenuto/Benvenuta>, {name}. Sei qui per unirti ai festeggiamenti?", 0x63b563a9, nil, 0xb5d3d793, nil, 0xb39733ba, ".m.m." },
  [8874] = { "Il Lunar Festival", nil, "È di nuovo quel periodo dell'anno, {name}! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare alla nostra celebrazione del Lunar Festival. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Ti racconterà di più sulla festa.", nil, "<Benvenuto/Benvenuta>, {name}. Sei qui per unirti ai festeggiamenti?", 0x63b563a9, nil, 0xb5d3d793, nil, 0xb39733ba, ".m.m." },
  [8875] = { "Il Lunar Festival", nil, "È di nuovo quel periodo dell'anno, {name}! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare alla nostra celebrazione del Lunar Festival. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Ti racconterà di più sulla festa.", nil, "<Benvenuto/Benvenuta>, {name}. Sei qui per unirti ai festeggiamenti?", 0x63b563a9, nil, 0xb5d3d793, nil, 0xb39733ba, ".m.m." },
  [8883] = { nil, "Usa il tuo Lunar Festival Invitation al chiaro di luna per andare a Moonglade. Quando arrivi, parla con Valadar Starsong a Nighthaven.", "Ora che hai il tuo Lunar Festival Invitation, puoi andare a Moonglade! Lì troverai molti festaioli, e nel villaggio di Nighthaven Valadar Starsong e sua sorella Fariel aspettano chi vuole partecipare alla celebrazione.\n\nVai a Moonglade attraverso la grande luce lunare e parla con Valadar Starsong; scopri quali premi potresti vincere durante la festa!", nil, "{name}, <benvenuto/benvenuta> a Nighthaven, sede del Lunar Festival! Anche se di solito il nostro villaggio è remoto e appartato dai popoli di Azeroth, durante questo periodo di festa apriamo le braccia e il cuore a tutti.\n\nGoditi la visita, {name}, e parla di nuovo con me o con mia sorella quando vuoi.", nil, 0x975b89d7, 0xc2988076, nil, 0x0fb6c30c, "m..m." },
  [8897] = { "Carissima Colara,", nil, nil, nil, nil, 0xc9e6996c, nil, nil, nil, nil, ".mmmm" },
  [8898] = { "Carissima Colara,", nil, nil, "Ciao, bel tipo. Posso aiutarti in qualcosa?", nil, 0xc9e6996c, nil, nil, 0x2cb6579e, nil, ".mm.m" },
  [8899] = { "Carissima Colara,", "Consegna l'Immaculate Letter a Colara Dean, fuori dalla banca di Stormwind.", "Come descrivere la sua bellezza? Migliaia di anni di parole e non so che dire.\n\nQuesti mortali confondono la mente e ci lasciano a balbettare come sciocchi.\n\nHo fissato queste parole troppo a lungo. Non riesco a spremerne un significato più eloquente. No, deve averla adesso, o qualche altro corteggiatore le ruberà di sicuro lo sguardo.", "Ciao, bel tipo. Posso aiutarti in qualcosa?", "Non ho mai ricevuto niente del genere. Che bello!", 0xc9e6996c, 0x46bb8540, 0x4e893ef6, 0x2cb6579e, 0x5e020085, "....." },
})
